mapper.update:
update qna_room
set status = #{status}
where room_no = #{roomNo}

mapper.select:
select room_no from qna_room
where status='QUESTION_OPEN'
  and question_ended_at <= #{now}

select room_no from qna_room
where status='VOTING_OPEN'
  and voting_ended_at <= #{now}

mapper.update:
update qna_room set status='QUESTION_CLOSED'
    where room_no=#{roomNo}
        and status = 'QUESTION_OPEN'
        and question_ended_at <= #{now}
